def semver_sort(versions):
    def parse_version(v):
        # Split off build metadata (after '+')
        if '+' in v:
            v_no_build = v.split('+')[0]
        else:
            v_no_build = v

        # Split core version and pre-release (after '-')
        if '-' in v_no_build:
            core, prerelease = v_no_build.split('-', 1)
        else:
            core = v_no_build
            prerelease = None

        # Parse core version (MAJOR.MINOR.PATCH)
        parts = core.split('.')
        major = int(parts[0])
        minor = int(parts[1]) if len(parts) > 1 else 0
        patch = int(parts[2]) if len(parts) > 2 else 0

        # Parse pre-release identifiers
        if prerelease:
            prerelease_ids = prerelease.split('.')
            # Convert identifiers: all-digits become ints, others stay as strings
            pre_parsed = []
            for identifier in prerelease_ids:
                if identifier.isdigit():
                    pre_parsed.append((0, int(identifier)))
                else:
                    pre_parsed.append((1, identifier))
        else:
            pre_parsed = None

        return (major, minor, patch, pre_parsed)

    def compare_key(v):
        major, minor, patch, pre_parsed = parse_version(v)

        # For sorting: versions without pre-release sort after versions with pre-release
        # So we use (major, minor, patch, is_release, pre_parsed)
        # where is_release=False for pre-release (sorts first), is_release=True for release (sorts after)

        if pre_parsed is None:
            # No pre-release: sorts after any pre-release of same version
            return (major, minor, patch, (1,), ())
        else:
            # Has pre-release: sorts before any release of same version
            # pre_parsed is already a list of (type, value) tuples for proper comparison
            return (major, minor, patch, (0,), tuple(pre_parsed))

    # Sort with stable sort (preserves input order for equal elements)
    return sorted(versions, key=compare_key)

